48	
49	impl Qwen3LoraOptions {
50	    const DEFAULT_MAX_LORAS: usize = 1;
51	    const DEFAULT_MAX_LORA_RANK: usize = 64;
52	    const SUPPORTED_MAX_LORA_RANKS: [usize; 9] = [1, 8, 16, 32, 64, 128, 256, 320, 512];
53	
54	    fn validate(self) -> Result<Self> {
55	        anyhow::ensure!(self.max_loras > 0, "max_loras must be >= 1");
56	        anyhow::ensure!(
57	            Self::is_supported_max_lora_rank(self.max_lora_rank),
58	            "max_lora_rank must be one of: {}",
59	            Self::supported_max_lora_ranks_display()
60	        );
61	        Ok(self)
62	    }
63	
64	    fn is_supported_max_lora_rank(rank: usize) -> bool {
65	        Self::SUPPORTED_MAX_LORA_RANKS.contains(&rank)
66	    }
67	
68	    fn supported_max_lora_ranks_display() -> String {
69	        Self::SUPPORTED_MAX_LORA_RANKS
70	            .iter()
71	            .map(usize::to_string)
72	            .collect::<Vec<_>>()
